INSERT INTO feature VALUES('reflexivity','identity','Reflexivity (Path.here)','identity-types','implemented','notable',NULL,'`Path.here(a)` is the identification of an element with itself, two reflexivities converting by their points, under a presented type''s rules too. An endpoint that applies the function a pure call returns is the bind over that call applying what it binds, in the engine and the kernel alike, and so is an endpoint that transports along the call''s path or acts on it. A run of a held call goes on through every definition it meets and through a held call an elimination stuck in it stands on, the kernel replaying the run by its own δ-steps, so a reflexivity whiskered twice is a unit of the composite. An action on an action is one path wherever the source writes the inner one, the engine reading the two endpoints the inner transport returns through and the kernel replaying the two motives as one.','core-checker core-nbe kernel-core','corpus/model/identity/here-congruence.gandr corpus/pathological/identity/here-congruence.gandr corpus/model/identity/nested-calls.gandr corpus/model/identity/a-run-through-a-held-path.gandr corpus/model/identity/a-held-run-through-two-definitions.gandr corpus/model/identity/a-transport-along-a-held-call.gandr corpus/model/identity/an-action-over-a-lambda-written-twice.gandr corpus/model/identity/ap-functoriality.gandr corpus/model/identity/actions-whose-arguments-reduce-alike.gandr corpus/model/identity/a-composite-lambda-against-its-two-lambdas.gandr corpus/model/identity/a-composite-by-a-definition-over-stuck-endpoints.gandr','corpus/model/identity/here-congruence.gandr',NULL);
